const body = $input.item.json.body || $input.item.json;
if (!body.video_id) throw new Error('video_id is required');
return {
  json: {
    job_id: body.job_id || 'job_media_' + Date.now(),
    video_id: body.video_id,
    scenes: body.scenes || [],
    plan_status: body.plan_status || 'APPROVED',
    received_at: new Date().toISOString()
  }
};

const input = $input.item.json;
const scenes = input.scenes || [];

// Group scenes by strategy for batched processing
const imageScenes = scenes.filter(s => s.mediaStrategy === 'AI_IMAGE' || s.mediaStrategy === 'MIXED');
const videoScenes = scenes.filter(s => s.mediaStrategy === 'AI_VIDEO');
const narrationScenes = scenes.filter(s => s.narration && s.narration.trim().length > 0);

return {
  json: {
    ...input,
    imageSceneCount: imageScenes.length,
    videoSceneCount: videoScenes.length,
    narrationSceneCount: narrationScenes.length,
    status: 'MEDIA_PREPARED'
  }
};
